                    opts.runtime_lang = val
                else:
                    try:
                        opts.runtime_lang = need_next("--lang", "lang")
                    except SystemExit as e:
                        return None, int(e.code)
            elif name == "--output":
                if eq:
                    opts.output = val
                else:
                    try:
                        opts.output = need_next("--output", "output")
                    except SystemExit as e:
                        return None, int(e.code)
            elif name == "--to":
                if eq:
                    opts.to = val
                else:
                    try:
                        opts.to = need_next("--to", "to", True)
                    except SystemExit as e:
                        return None, int(e.code)
                if opts.to not in TO_CHOICES:
                    return None, invalid_to(opts.to)
            elif name == "--print-template":
                if eq:
                    opts.print_template = val
                else:
                    try:
                        opts.print_template = need_next("--print-template", "print-template")
                    except SystemExit as e:
                        return None, int(e.code)
            elif name == "--create":
                vals: List[str] = []
                if eq and val:
                    vals.append(val)
                j = i + 1
                while j < len(argv) and not argv[j].startswith('-'):
                    vals.append(argv[j]); j += 1
                if not vals:
                    stderr_write("error: a value is required for '--create <files>...' but none was supplied\n")
                    stderr_write("\nFor more information, try '--help'.\n")
                    return None, 2
                opts.create = vals
                i = j - 1
            elif name == "--set":
