                        i += 1; val = argv[i]
                    if ch == 't':
                        opts.to = val
                        if opts.to not in TO_CHOICES: return None, invalid_to(opts.to)
                    elif ch == 'o':
                        opts.output = val
                    elif ch == 'L':
