def strip_comment_value(s: str) -> str:
    quote: Optional[str] = None
    out = []
    esc = False
    for ch in s:
        if esc:
            out.append(ch); esc = False; continue
        if ch == '\\':
            out.append(ch); esc = True; continue
        if quote:
            out.append(ch)
            if ch == quote:
                quote = None
            continue
        if ch in ('"', "'"):
            quote = ch; out.append(ch); continue
        if ch == '#':
            break
        out.append(ch)
    return ''.join(out).strip()


def unquote_value(v: str) -> str:
    v = v.strip()
    if len(v) >= 2 and ((v[0] == v[-1] == '"') or (v[0] == v[-1] == "'")):
        v = v[1:-1]
        v = v.replace('\\"', '"').replace("\\'", "'")
    return v


def parse_list_value(v: str) -> Optional[List[str]]:
    v = v.strip()
    if not (v.startswith('[') and v.endswith(']')):
        return None
    inner = v[1:-1].strip()
    if not inner:
        return []
    return [unquote_value(x.strip()) for x in inner.split(',') if x.strip()]


def yamlish_kind(v: str) -> str:
    v = v.strip()
    if v.startswith('[') and v.endswith(']'):
        return "Sequence"
    if v.lower() in ("true", "false"):
        return "Bool"
    if re.fullmatch(r"[-+]?\d+", v):
        return "Integer"
    return f"String(\"{unquote_value(v)}\")"


def set_book_option(book: Book, key: str, raw_value: str, line: int, context_file: Optional[Path] = None, prefix: str = "") -> bool:
    key = key.strip()
    value_text = strip_comment_value(raw_value)
    if key not in KNOWN_KEYS:
        file_display = str(context_file or book.source)
        book.errors.append(ConfigError("ERROR", f"{file_display}:{line}: Error converting BookOption: unrecognized key '{key}'"))
        return False
    if key in LIST_KEYS:
        arr = parse_list_value(value_text)
        if arr is None:
            file_display = str(context_file or book.source)
            book.errors.append(ConfigError("ERROR", f"{file_display}:{line}: Error converting BookOption: Expected a list as value for key {key}, found {yamlish_kind(value_text)}"))
            return False
        book.opts[key] = arr
        return True
    if key in INT_KEYS:
        val = unquote_value(value_text)
        if not re.fullmatch(r"[-+]?\d+", val):
            file_display = str(context_file or book.source)
            book.errors.append(ConfigError("ERROR", f"{file_display}:{line}: Error converting BookOption: expected an integer as value for key '{key}', found {yamlish_kind(value_text)}"))
            return False
        book.opts[key] = int(val)
        return True
    if key in BOOL_KEYS:
        val = unquote_value(value_text).lower()
        if val not in ("true", "false"):
            file_display = str(context_file or book.source)
            book.errors.append(ConfigError("ERROR", f"{file_display}:{line}: Error converting BookOption: expected a boolean as value for key '{key}', found {yamlish_kind(value_text)}"))
            return False
        book.opts[key] = (val == "true")
        return True
    # Metadata/path/string: keep as string. A list-ish value is rendered as raw
    # text by the original for most such keys, so no extra validation here.
    book.opts[key] = unquote_value(value_text)
    return True


def parse_config_file(path: Path, imported: bool = False, into: Optional[Book] = None) -> Book:
    path = Path(path)
    book = into if into is not None else Book(source=path, base_dir=path.parent if path.parent != Path('') else Path('.'))
    try:
        text = path.read_text(encoding='utf-8')
    except FileNotFoundError:
        if into is None:
            book.fatal = f"Could not find file '{path}' for book"
        else:
            book.errors.append(ConfigError("ERROR", f"Could not find file '{path}' for book"))
        return book
    except OSError as e:
        if into is None:
            book.fatal = f"Could not find file '{path}' for book"
        else:
            book.errors.append(ConfigError("ERROR", f"Could not find file '{path}' for book"))
        return book

    lines = text.splitlines()
    for idx, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped:
            continue
        if stripped.startswith('#'):
            continue
        first = stripped[0]
        if first in '+-!':
            if imported:
                continue
            target = stripped[1:].strip()
            if re.search(r"\s", target):
                book.fatal = f"{path}:{idx}: Error parsing configuration file: error.chapter_whitespace"
                return book
            book.chapters.append(ChapterSpec(first, target, idx))
            continue
        if first == '@':
            if not imported:
                book.chapters.append(ChapterSpec('@', stripped[1:].strip(), idx))
            continue
        if ':' in line:
            key, val = line.split(':', 1)
            key = key.strip()
            if key == "import":
                imp = unquote_value(strip_comment_value(val))
                imp_path = Path(imp)
                if not imp_path.is_absolute():
                    imp_path = (path.parent if path.parent != Path('') else Path('.')) / imp_path
                # Import options only, not chapter list.
                parse_config_file(imp_path, imported=True, into=book)
            else:
                set_book_option(book, key, val, idx, path)
            continue
        book.fatal = (f"{path}:{idx}: Error parsing configuration file: \"could not parse %{{file}} as a book file.\"\n"
                      "Maybe you meant to run crowbook with the --single argument?\n")
        return book
    return book


def parse_single_markdown(path: Path) -> Book:
    book = Book(source=path, base_dir=path.parent if path.parent != Path('') else Path('.'))
    try:
        text = path.read_text(encoding='utf-8')
    except FileNotFoundError:
        book.fatal = f"{path}: Could not find file '{path}' for book chapter"
        return book
    except OSError:
        book.fatal = f"{path}: Could not find file '{path}' for book chapter"
        return book
    body = text
    lines = text.splitlines()
    if lines and lines[0].strip() == '---':
        end = None
        for i in range(1, len(lines)):
            if lines[i].strip() == '---':
                end = i
                break
        if end is not None:
            meta_lines = lines[1:end]
            for idx, line in enumerate(meta_lines, start=2):
                if not line.strip() or line.strip().startswith('#'):
                    continue
                if ':' in line:
                    key, val = line.split(':', 1)
                    set_book_option(book, key.strip(), val, idx, path)
            body = '\n'.join(lines[end + 1:])
            if text.endswith('\n'):
                body += '\n'
    book.single_body = body
    book.chapters.append(ChapterSpec('+', str(path), 1))
    return book


# ---------------------------------------------------------------------------
# Markdown rendering

@dataclass
class RenderState:
    book: Book
    html: bool = True
    link_counter: int = 1
    para_counter: int = 1
    chapter_counter: int = 0
    part_counter: int = 0
    section_stack: List[int] = field(default_factory=lambda: [0, 0, 0, 0, 0, 0])
    toc: List[Tuple[str, str, str]] = field(default_factory=list)  # href, label, kind
    warnings: List[ConfigError] = field(default_factory=list)
    image_error: Optional[str] = None


def roman(n: int) -> str:
    vals = [(1000,'M'),(900,'CM'),(500,'D'),(400,'CD'),(100,'C'),(90,'XC'),(50,'L'),(40,'XL'),(10,'X'),(9,'IX'),(5,'V'),(4,'IV'),(1,'I')]
    out = []
    for v, s in vals:
        while n >= v:
            out.append(s); n -= v
    return ''.join(out) or '0'


def lang_chapter(book: Book) -> str:
    custom = book.opts.get("rendering.chapter")
    if custom:
        return str(custom)
    return "Chapitre" if str(book.opts.get("lang", "en")).startswith('fr') else "Chapter"


def lang_part(book: Book) -> str:
    custom = book.opts.get("rendering.part")
    if custom:
        return str(custom)
    return "Partie" if str(book.opts.get("lang", "en")).startswith('fr') else "Part"


def clean_text(text: str, book: Book) -> str:
    if not bool(book.opts.get("input.clean", True)):
        return text
    if bool(book.opts.get("input.clean.smart_quotes", True)):
        # A deterministic, lightweight smart quote pass.
        res = []
        open_d = True
        for ch in text:
            if ch == '"':
                res.append('“' if open_d else '”'); open_d = not open_d
            else:
                res.append(ch)
        text = ''.join(res)
        # Apostrophes between letters are closing apostrophes; remaining pairs alternate.
        text = re.sub(r"(?<=\w)'(?=\w)", "’", text)
        res = []
        open_s = True
        for ch in text:
            if ch == "'":
                res.append('‘' if open_s else '’'); open_s = not open_s
            else:
                res.append(ch)
        text = ''.join(res)
    if bool(book.opts.get("input.clean.ligature.dashes", False)):
        text = text.replace('---', '—').replace('--', '–')
    if str(book.opts.get("lang", "en")).startswith('fr'):
        text = text.replace('...', '…')
        if bool(book.opts.get("input.clean.ligature.guillemets", False)):
            text = text.replace('<<', '«').replace('>>', '»')
    return text


def apply_french_nbsp_escaped(escaped: str, book: Book, epub: bool = False) -> str:
    if not str(book.opts.get("lang", "en")).startswith('fr'):
        return escaped
    if not bool(book.opts.get("html.escape_nb_spaces", True)):
        return escaped
    # Approximation of Crowbook's non-breaking-space cleaning before high
    # punctuation. Keep it as an entity after escaping.
    escaped = re.sub(r"\s+([!?:;])", r"&#160;\1", escaped)
    return escaped


def escape_html_text(text: str, book: Book) -> str:
    text = clean_text(text, book)
    esc = htmlmod.escape(text, quote=False)
    esc = apply_french_nbsp_escaped(esc, book)
    return esc


def inline_stats_text(src: str, book: Book) -> str:
    s = re.sub(r"!\[[^\]]*\]\([^)]*\)", "", src)
    s = re.sub(r"\[([^\]]+)\]\([^)]*\)", r"\1", s)
    s = re.sub(r"`([^`]*)`", r"\1", s)
    s = re.sub(r"\*\*([^*]+)\*\*", r"\1", s)
    s = re.sub(r"\*([^*]+)\*", r"\1", s)
    s = re.sub(r"__([^_]+)__", r"\1", s)
    s = re.sub(r"_([^_]+)_", r"\1", s)
    s = re.sub(r"<[^>]+>", lambda m: m.group(0), s)  # tags count as text if present before escaping
    return clean_text(s, book)


def local_path_for(md_path: Path, target: str) -> Path:
    p = Path(target)
    if p.is_absolute():
        return p
    return (md_path.parent if md_path.parent != Path('') else Path('.')) / p


def render_inline(src: str, book: Book, md_path: Path, state: RenderState) -> str:
    # Tokenize image/link/code/emphasis enough for common Markdown.
    placeholders: List[str] = []

    def put(x: str) -> str:
        placeholders.append(x)
        return f"\u0000{len(placeholders)-1}\u0000"

    def image_repl(m: re.Match) -> str:
        alt, url = m.group(1), m.group(2).strip()
        if not re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*:", url):
            p = local_path_for(md_path, url)
            if not p.exists():
                disp = url if url.startswith('.') else './' + url
                state.image_error = f"{md_path.name}: Could not find file '{disp}' for image"
                return ""
            data = p.read_bytes()
            mime = mimetypes.guess_type(str(p))[0] or "application/octet-stream"
            b64 = base64.b64encode(data).decode('ascii').rstrip('=')
            return put(f'<img src = "data:{mime};base64,{b64}" title = "" alt = "{htmlmod.escape(clean_text(alt, book), quote=True)}" />')
        return put(f'<img src = "{htmlmod.escape(url, quote=True)}" title = "" alt = "{htmlmod.escape(clean_text(alt, book), quote=True)}" />')

    src = re.sub(r"!\[([^\]]*)\]\(([^)]*)\)", image_repl, src)

    def code_repl(m: re.Match) -> str:
        return put(f"<code>{escape_html_text(m.group(1), book)}</code>")
    src = re.sub(r"`([^`]*)`", code_repl, src)

    def link_repl(m: re.Match) -> str:
        text, url = m.group(1), m.group(2).strip()
        inner = render_inline(text, book, md_path, state)
        if not re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*:", url) and not url.startswith('#'):
            # The reference warns for local links that do not point to a known chapter.
            # Keep warning wording for obvious standalone local files.
            pass
        return put(f'<a href = "{htmlmod.escape(url, quote=True)}">{inner}</a>')
    src = re.sub(r"\[([^\]]+)\]\(([^)]*)\)", link_repl, src)

    # Escape remaining text, then restore placeholders.
    s = escape_html_text(src, book)

    def strong(m: re.Match) -> str:
        return f"<b>{m.group(1)}</b>"
    def emph(m: re.Match) -> str:
        return f"<em>{m.group(1)}</em>"
    s = re.sub(r"\*\*([^*]+)\*\*", strong, s)
    s = re.sub(r"__([^_]+)__", strong, s)
    s = re.sub(r"\*([^*]+)\*", emph, s)
    s = re.sub(r"_([^_]+)_", emph, s)

    def restore(m: re.Match) -> str:
        return placeholders[int(m.group(1))]
    s = re.sub("\u0000(\d+)\u0000", restore, s)
    return s


def render_paragraph(lines: List[str], book: Book, md_path: Path, state: RenderState) -> Tuple[str, str]:
    # Markdown hard break: two trailing spaces before a line break.
    pieces = []
    stat = []
    for idx, line in enumerate(lines):
        hard = line.endswith('  ')
        content = line[:-2] if hard else line
        pieces.append(render_inline(content, book, md_path, state))
        stat.append(inline_stats_text(content, book))
        if hard:
            pieces.append('<br />\n')
        elif idx != len(lines) - 1:
            pieces.append('\n')
    pid = state.para_counter; state.para_counter += 1
    return f'<p id = "para-{pid}">' + ''.join(pieces) + '</p>', ''.join(stat)


def heading_number_prefix(level: int, state: RenderState, book: Book) -> str:
    depth = int(book.opts.get("rendering.num_depth", 1) or 0)
    if depth < level or level <= 1:
        return ""
    # Increment this level and reset deeper counters. H1 counter is chapter_counter.
    state.section_stack[level-1] += 1
    for i in range(level, len(state.section_stack)):
        state.section_stack[i] = 0
    nums = [state.chapter_counter] + state.section_stack[1:level]
    return '.'.join(str(n) for n in nums if n) + '. '


def make_toc_label(number: str, title: str, marker: str, book: Book, part: bool = False) -> str:
    if part:
        tmpl = str(book.opts.get("rendering.part.template", "{{number}}. {{part_title}}"))
        return tmpl.replace("{{number}}", number).replace("{{part_title}}", title)
    if marker == '+':
        tmpl = str(book.opts.get("rendering.chapter.template", "{{number}}. {{chapter_title}}"))
        return tmpl.replace("{{number}}", number).replace("{{chapter_title}}", title)
    return title


def render_h1(title_src: str, marker: str, book: Book, state: RenderState, md_path: Path) -> str:
    title_text = inline_stats_text(title_src, book)
    link = state.link_counter; state.link_counter += 1
    depth = int(book.opts.get("rendering.num_depth", 1) or 0)
    if marker == '+' and depth > 0:
        state.chapter_counter += 1
        state.section_stack = [0, 0, 0, 0, 0, 0]
        num = roman(state.chapter_counter) if bool(book.opts.get("rendering.chapter.roman_numerals", False)) else str(state.chapter_counter)
        state.toc.append((f"#link-{link}", make_toc_label(num, title_text, marker, book), "chapter"))
        header = f"{lang_chapter(book)} {num}"
        title_html = render_inline(title_src, book, md_path, state)
        if title_text:
            return f"<h1 id = 'link-{link}'><span class = 'chapter-header'>{htmlmod.escape(header)}</span><br />{title_html}</h1>"
        return f"<h1 id = 'link-{link}'><span class = 'chapter-header'>{htmlmod.escape(header)}</span></h1>"
    if marker == '!' and depth > 0:
        state.toc.append((f"#link-{link}", title_text, "chapter"))
        return f'<h1 id = "link-{link}"></h1>'
    # Unnumbered or no-number-depth.
    if depth > 0 and title_text:
        state.toc.append((f"#link-{link}", title_text, "chapter"))
    title_html = render_inline(title_src, book, md_path, state)
    return f'<h1 id = "link-{link}">{title_html}</h1>'


def render_markdown_body(text: str, book: Book, md_path: Path, marker: str, state: RenderState) -> Tuple[str, str, bool]:
    lines = text.splitlines()
    out: List[str] = []
    stats_parts: List[str] = []
    saw_h1 = False
    i = 0

    def ensure_initial_chapter() -> None:
        nonlocal saw_h1
        if saw_h1:
            return
        if marker == '+' and int(book.opts.get("rendering.num_depth", 1) or 0) > 0:
            # A numbered file without an H1 still gets a chapter heading and TOC item.
            saw_h1 = True
            link = state.link_counter; state.link_counter += 1
            state.chapter_counter += 1
            state.section_stack = [0, 0, 0, 0, 0, 0]
            num = roman(state.chapter_counter) if bool(book.opts.get("rendering.chapter.roman_numerals", False)) else str(state.chapter_counter)
            state.toc.append((f"#link-{link}", make_toc_label(num, "", marker, book), "chapter"))
            out.append(f"<h1 id = 'link-{link}'><span class = 'chapter-header'>{htmlmod.escape(lang_chapter(book))} {num}</span></h1>")

    while i < len(lines):
        line = lines[i]
        stripped = line.strip()
        if stripped == '':
            i += 1; continue
        # Fenced code block
        m = re.match(r"^```\s*([^`]*)$", line)
        if m:
            ensure_initial_chapter()
            lang = m.group(1).strip()
            i += 1; code_lines = []
            while i < len(lines) and not lines[i].startswith('```'):
                code_lines.append(lines[i]); i += 1
            if i < len(lines): i += 1
            code = '\n'.join(code_lines) + '\n'
            stats_parts.append(code)
            esc = htmlmod.escape(code, quote=False)
            if lang:
                out.append(f'<pre><code class = "language-{htmlmod.escape(lang, quote=True)}">{esc}</code></pre>')
            else:
                out.append(f'<pre><code>{esc}</code></pre>')
            continue
        # Heading
        hm = re.match(r"^(#{1,6})\s+(.*?)\s*#*\s*$", line)
        if hm:
            level = len(hm.group(1)); title_src = hm.group(2)
            if level == 1:
                saw_h1 = True
                stats_parts.append(inline_stats_text(title_src, book))
                out.append(render_h1(title_src, marker, book, state, md_path))
            else:
                ensure_initial_chapter()
                stats_parts.append(inline_stats_text(title_src, book))
                link = state.link_counter; state.link_counter += 1
                prefix = heading_number_prefix(level, state, book)
                out.append(f'<h{level} id = "link-{link}">{htmlmod.escape(prefix)}{render_inline(title_src, book, md_path, state)}</h{level}>')
            i += 1; continue
        # Rule
        if stripped in ('---', '***', '* * *'):
            ensure_initial_chapter()
            out.append('<p class = "rule">***</p>')
            i += 1; continue
        # Block quote (simple)
        if line.lstrip().startswith('>'):
            ensure_initial_chapter()
            qlines = []
            while i < len(lines) and lines[i].lstrip().startswith('>'):
                qlines.append(lines[i].lstrip()[1:].lstrip())
                i += 1
            p, st = render_paragraph(qlines, book, md_path, state)
            stats_parts.append(st)
            out.append('<blockquote>' + p + '\n</blockquote>')
            continue
        # Lists
        if re.match(r"^\s*([-*])\s+\S", line) or re.match(r"^\s*\d+\.\s+\S", line):
            ensure_initial_chapter()
            ordered = bool(re.match(r"^\s*\d+\.\s+", line))
            tag = 'ol' if ordered else 'ul'
            out.append(f'<{tag}>')
            while i < len(lines):
                lm = re.match(r"^\s*(?:[-*]|\d+\.)\s+(.*)$", lines[i])
                if not lm:
                    break
                item = lm.group(1)
                p, st = render_paragraph([item], book, md_path, state)
                stats_parts.append(st)
                out.append('<li>' + p + '\n</li>')
                i += 1
            out.append(f'</{tag}>')
            continue
        # Paragraph
        ensure_initial_chapter()
        plines = []
        while i < len(lines):
            l = lines[i]
            if not l.strip():
                break
            if re.match(r"^```", l) or re.match(r"^(#{1,6})\s+", l) or l.strip() in ('---','***','* * *') or l.lstrip().startswith('>') or re.match(r"^\s*(?:[-*]|\d+\.)\s+\S", l):
                break
            plines.append(l); i += 1
        if plines:
            p, st = render_paragraph(plines, book, md_path, state)
            stats_parts.append(st)
            out.append(p)
        else:
            i += 1
    if not saw_h1 and marker == '+' and not out:
        ensure_initial_chapter()
    return '\n'.join(out), ''.join(stats_parts), saw_h1


@dataclass
class Rendered:
    chapter_divs: List[str]
    chapter_chunks: List[str]
    stats_rows: List[Tuple[str, int, int]]
    toc: List[Tuple[str, str, str]]
    warnings: List[ConfigError]
    error: Optional[str] = None


def render_book_model(book: Book) -> Rendered:
    state = RenderState(book=book)
    chapter_divs: List[str] = []
    chapter_chunks: List[str] = []
    stats_rows: List[Tuple[str, int, int]] = []
    if book.single_body is not None:
        md_path = book.source
        body, stat_text, _ = render_markdown_body(book.single_body, book, md_path, '+', state)
        if state.image_error:
            return Rendered([], [], [], [], state.warnings, state.image_error)
        chapter_divs.append(f'<div id = "chapter-0" class = "chapter">\n  {body}\n</div>')
        chapter_chunks.append(body)
        stats_rows.append((book.source.name, len(stat_text), len(stat_text.split())))
    else:
        file_index = 0
        for spec in book.chapters:
            if spec.marker == '@':
                state.part_counter += 1
                num = roman(state.part_counter) if bool(book.opts.get("rendering.part.roman_numerals", True)) else str(state.part_counter)
                title = spec.target
                link = state.link_counter; state.link_counter += 1
                state.toc.append((f"#link-{link}", make_toc_label(num, title, '@', book, part=True), "part"))
                html = f"<h2 class = 'part'>{htmlmod.escape(lang_part(book))} {num}</h2> <h1 id = 'link-{link}' class = 'part'>{htmlmod.escape(title)}</h1>"
                chapter_divs.append(f'<div id = "chapter-{file_index}" class = "chapter">\n  {html}\n</div>')
                chapter_chunks.append(html)
                stats_rows.append(("", len(title), len(title.split())))
                file_index += 1
                if bool(book.opts.get("rendering.part.reset_counter", True)):
                    state.chapter_counter = 0
                continue
            md_path = Path(spec.target)
            if not md_path.is_absolute():
                md_path = book.base_dir / md_path
            if not md_path.exists():
                return Rendered([], [], [], [], state.warnings, f"{book.source}:{spec.line}: Could not find file '{md_path}' for book chapter")
            try:
                text = md_path.read_text(encoding='utf-8')
            except OSError:
                return Rendered([], [], [], [], state.warnings, f"{book.source}:{spec.line}: Could not find file '{md_path}' for book chapter")
            body, stat_text, _ = render_markdown_body(text, book, md_path, spec.marker, state)
            if state.image_error:
                return Rendered([], [], [], [], state.warnings, state.image_error)
            chapter_divs.append(f'<div id = "chapter-{file_index}" class = "chapter">\n  {body}\n</div>')
            chapter_chunks.append(body)
            stats_rows.append((spec.target, len(stat_text), len(stat_text.split())))
            file_index += 1
    return Rendered(chapter_divs, chapter_chunks, stats_rows, state.toc, state.warnings)


# ---------------------------------------------------------------------------
# Output renderers

MENU_SVG_PLACEHOLDER = "data:image/svg+xml;base64,"


def html_style() -> str:
    return TEMPLATES.get('html.css', 'body { font-family: serif; }\n') + "\n" + TEMPLATES.get('html.css.colors', '')


def render_html_document(book: Book) -> Tuple[Optional[str], List[ConfigError], Optional[str]]:
    rendered = render_book_model(book)
    if rendered.error:
        return None, rendered.warnings, rendered.error
    title = str(book.opts.get('title', ''))
    author = str(book.opts.get('author', ''))
    lang = str(book.opts.get('lang', 'en'))
    warnings = list(rendered.warnings)
    parts: List[str] = []
    parts.append('<!DOCTYPE html>')
    parts.append(f'<html lang="{htmlmod.escape(lang, quote=True)}">')
    parts.append('  <head>')
    parts.append('    <meta charset="utf-8">')
    parts.append('    <meta name="generator" content="crowbook">')
    parts.append('    <meta name="viewport" content="width=device-width">')
    parts.append(f'    <meta name="author" content="{htmlmod.escape(author, quote=True)}">')
    parts.append('    ')
    parts.append(f'    <title>{htmlmod.escape(title)}</title>')
    parts.append('    <style type = "text/css">')
    parts.append(html_style())
    css_add = book.opts.get('html.css.add')
    if css_add:
        parts.append(str(css_add))
    parts.append('    </style>')
    parts.append('  </head>')
    parts.append('  <body>')
    if len(rendered.toc) > 1:
        parts.append('    <nav id = "nav">')
        parts.append(f'      <h2><a href="#link-0">{htmlmod.escape(title)}</a></h2>')
        parts.append('          <ul>')
        for href, label, _kind in rendered.toc:
            parts.append(f'      <li><a href="{href}">{htmlmod.escape(label)}</a></li>')
        parts.append('    </ul>')
        parts.append('    </nav>')
    parts.append('')
    parts.append('    <div id = "content">')
    parts.append('      ')
    parts.append('      <div id = "page">')
    parts.append('        <header>')
    parts.append('')
    parts.append('          <div id = "menu">')
    alt = 'Table des matières' if lang.startswith('fr') else 'Table of contents'
    parts.append(f'            <img id = "menu-button" onclick="toggle();" src="{MENU_SVG_PLACEHOLDER}" alt = "{alt}" title = "{alt}" />')
    parts.append('          </div>')
    header_extra = book.opts.get('html.header')
    if header_extra:
        parts.append(str(header_extra))
    parts.append(f'\t  <h2 class="author">{htmlmod.escape(author)}</h2>')
    parts.append(f'          <h1 id = "link-0" class="title" >{htmlmod.escape(title)}</h1>')
    subtitle = book.opts.get('subtitle')
    if subtitle:
        parts.append(f'          <h2 class="subtitle">{htmlmod.escape(str(subtitle))}</h2>')
    autograph = book.opts.get('autograph')
    if autograph:
        parts.append('\t  <div id = "autograph">')
        parts.append(f'\t    {htmlmod.escape(str(autograph))}')
        parts.append('\t  </div>')
    parts.append('        </header>')
    parts.append('')
    parts.extend('        ' + div for div in rendered.chapter_divs)
    footer_extra = book.opts.get('html.footer')
    if footer_extra:
        parts.append(str(footer_extra))
    parts.append('')
    parts.append('      </div>')
    parts.append('      ')
    parts.append('    </div>')
    parts.append('  </body>')
    parts.append('</html>')
    return '\n'.join(parts) + '\n', warnings, None


def latex_escape(s: str) -> str:
    repl = {'\\': r'\textbackslash{}', '&': r'\&', '%': r'\%', '$': r'\$', '#': r'\#', '_': r'\_', '{': r'\{', '}': r'\}', '~': r'\textasciitilde{}', '^': r'\textasciicircum{}'}
    return ''.join(repl.get(c, c) for c in s)


def markdown_to_latex(text: str, book: Book, single: bool = False) -> str:
    lines = text.splitlines()
    out = []
    in_code = False; code_lines = []
    for line in lines:
        m = re.match(r"^```", line)
        if m:
            if not in_code:
                in_code = True; code_lines = []
            else:
                out.append('\\begin{mdcodeblock}')
                out.append('\\begin{spverbatim}')
                out.extend(code_lines)
                out.append('')
                out.append('\\end{spverbatim}')
                out.append('\\end{mdcodeblock}')
                in_code = False
            continue
        if in_code:
            code_lines.append(line); continue
        hm = re.match(r"^(#{1,6})\s+(.*?)\s*#*\s*$", line)
        if hm:
            lvl = len(hm.group(1)); title = latex_escape(inline_stats_text(hm.group(2), book))
            if single:
                cmd = ['section','subsection','subsubsection','paragraph','subparagraph','subparagraph'][min(lvl-1,5)]
            else:
                cmd = ['chapter','section','subsection','subsubsection','paragraph','subparagraph'][min(lvl-1,5)]
            out.append(f'\\{cmd}' + '{' + title + '}')
            if lvl == 1: out.append('\\label{chapter-0}')
            continue
        if not line.strip():
            out.append(''); continue
        if line.strip() in ('---', '***', '* * *'):
            out.append('\\mdrule'); continue
        # Simple inline conversions.
        s = inline_stats_text(line, book)
        s = latex_escape(s)
        s = re.sub(r"\*\*([^*]+)\*\*", r"\\mdstrong{\1}", s)
        out.append(s)
    return '\n'.join(out)


def render_tex_document(book: Book) -> Tuple[Optional[str], List[ConfigError], Optional[str]]:
    # Validate/render model first to catch missing images/chapters consistently.
    rendered = render_book_model(book)
    if rendered.error:
        return None, rendered.warnings, rendered.error
    cls = 'article' if book.single_body is not None else str(book.opts.get('tex.class', 'book') or 'book')
    title = latex_escape(str(book.opts.get('title', '')))
    author = latex_escape(str(book.opts.get('author', '')))
    lang = str(book.opts.get('lang', 'en'))
    babel = 'french' if lang.startswith('fr') else 'english'
    parts = [
        f'\\documentclass{{{cls}}}', '', '%% Package inclusion', '',
        '% Unicode support if xelatex is used', '\\usepackage{fontspec}', '\\usepackage{xunicode}', '',
        f'\\usepackage[{babel}]{{babel}} % Language support', '\\usepackage{hyperref}', '\\usepackage{spverbatim}',
        '\\newcommand\\mdstrong[1]{\\textbf{#1}}', '\\newcommand\\mdcode[1]{\\texttt{#1}}',
        '\\newcommand\\mdrule{\\begin{center}***\\end{center}}', '\\newcommand\\mdhardbreak{\\\\}',
        '\\newenvironment{mdcodeblock}{\\begin{quote}}{\\end{quote}}', '',
        f'\\title{{{title}}}', f'\\author{{{author}}}', '', '\\begin{document}', '', '\\maketitle', '',
    ]
    if book.single_body is not None:
        parts.append(markdown_to_latex(book.single_body, book, single=True))
    else:
        for spec in book.chapters:
            if spec.marker == '@':
                parts.append('\\part{' + latex_escape(spec.target) + '}')
                continue
            md_path = Path(spec.target)
            if not md_path.is_absolute(): md_path = book.base_dir / md_path
            try:
                text = md_path.read_text(encoding='utf-8')
            except OSError:
                return None, [], f"{book.source}:{spec.line}: Could not find file '{md_path}' for book chapter"
            parts.append(markdown_to_latex(text, book, single=False))
    parts.extend(['', '\\end{document}', ''])
    return '\n'.join(parts), rendered.warnings, None


def render_epub_bytes(book: Book) -> Tuple[Optional[bytes], List[ConfigError], Optional[str]]:
    rendered = render_book_model(book)
    warnings = list(rendered.warnings)
    if rendered.error:
        return None, warnings, rendered.error
    warnings.append(ConfigError("WARNING", "Could not run zip command, falling back to zip library"))
    title = str(book.opts.get('title', ''))
    author = str(book.opts.get('author', ''))
    lang = str(book.opts.get('lang', 'en'))
    version = int(book.opts.get('epub.version', 2) or 2)
    mem = io.BytesIO()
    with zipfile.ZipFile(mem, 'w', compression=zipfile.ZIP_DEFLATED) as z:
        zi = zipfile.ZipInfo('mimetype')
        zi.compress_type = zipfile.ZIP_STORED
        z.writestr(zi, 'application/epub+zip')
        z.writestr('META-INF/container.xml', '<?xml version="1.0" encoding="UTF-8"?>\n<container version="1.0" xmlns="urn:oasis:names:tc:opendocument:xmlns:container">\n  <rootfiles>\n    <rootfile full-path="OEBPS/content.opf" media-type="application/oebps-package+xml" />\n  </rootfiles>\n</container>\n')
        z.writestr('META-INF/com.apple.ibooks.display-options.xml', '<?xml version="1.0" encoding="UTF-8"?>\n<display_options>\n  <platform name="*">\n    <option name="specified-fonts">true</option>\n  </platform>\n</display_options>\n')
        z.writestr('OEBPS/stylesheet.css', TEMPLATES.get('epub.css', html_style()))
        title_page = f'''<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.1//EN" "http://www.w3.org/TR/xhtml11/DTD/xhtml11.dtd">
<html xmlns="http://www.w3.org/1999/xhtml" xml:lang="{htmlmod.escape(lang)}">
<head><title>{htmlmod.escape(title)}</title><link rel="stylesheet" type="text/css" href="stylesheet.css" /></head>
<body>
  <h2 class="author">{htmlmod.escape(author)}</h2>
  <h1 class="title">{htmlmod.escape(title)}</h1>
</body>
</html>
'''
        z.writestr('OEBPS/title_page.xhtml', title_page)
        manifest_items = ['<item id="title_page" href="title_page.xhtml" media-type="application/xhtml+xml" />', '<item id="style" href="stylesheet.css" media-type="text/css" />']
        spine_items = ['<itemref idref="title_page" />']
        navpoints = []
        for idx, chunk in enumerate(rendered.chapter_chunks):
            name = f'chapter_{idx:03d}.xhtml'
            xhtml = f'''<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.1//EN" "http://www.w3.org/TR/xhtml11/DTD/xhtml11.dtd">
<html xmlns="http://www.w3.org/1999/xhtml" xml:lang="{htmlmod.escape(lang)}" lang="{htmlmod.escape(lang)}">
  <head><meta http-equiv="Content-Type" content="text/html; charset=utf-8" /><meta name="generator" content="crowbook" /><title>{htmlmod.escape(title)}</title><link rel="stylesheet" type="text/css" href="stylesheet.css" /></head>
  <body xml:lang="{htmlmod.escape(lang)}" lang="{htmlmod.escape(lang)}"><div id = "page">
{chunk}
  </div></body>
</html>
'''
            z.writestr('OEBPS/' + name, xhtml)
            manifest_items.append(f'<item id="chapter_{idx:03d}" href="{name}" media-type="application/xhtml+xml" />')
            spine_items.append(f'<itemref idref="chapter_{idx:03d}" />')
            label = rendered.toc[idx][1] if idx < len(rendered.toc) else f'Chapter {idx+1}'
            navpoints.append(f'<navPoint id="navPoint-{idx+1}" playOrder="{idx+1}"><navLabel><text>{htmlmod.escape(label)}</text></navLabel><content src="{name}" /></navPoint>')
        manifest_items.append('<item id="ncx" href="toc.ncx" media-type="application/x-dtbncx+xml" />')
        if version >= 3:
            manifest_items.append('<item id="nav" href="nav.xhtml" media-type="application/xhtml+xml" properties="nav" />')
        opf = f'''<?xml version="1.0" encoding="UTF-8"?>
<package version="{version}.0" xmlns="http://www.idpf.org/2007/opf" unique-identifier="epub-id-1">
  <metadata xmlns:dc="http://purl.org/dc/elements/1.1/">
    <dc:title>{htmlmod.escape(title)}</dc:title>
    <dc:creator>{htmlmod.escape(author)}</dc:creator>
    <dc:language>{htmlmod.escape(lang)}</dc:language>
    <dc:identifier id="epub-id-1">urn:uuid:crowbook-reimplementation</dc:identifier>
  </metadata>
  <manifest>
    {' '.join(manifest_items)}
  </manifest>
  <spine toc="ncx">
    {' '.join(spine_items)}
  </spine>
</package>
'''
        z.writestr('OEBPS/content.opf', opf)
        ncx = f'''<?xml version="1.0" encoding="UTF-8"?>
<ncx version="2005-1" xmlns="http://www.daisy.org/z3986/2005/ncx/">
  <head><meta name="dtb:depth" content="1" /><meta name="dtb:totalPageCount" content="0" /><meta name="dtb:maxPageNumber" content="0" /></head>
  <docTitle><text>{htmlmod.escape(title)}</text></docTitle>
  <navMap>{''.join(navpoints)}</navMap>
</ncx>
'''
        z.writestr('OEBPS/toc.ncx', ncx)
        if version >= 3:
            navlis = ''.join(f'<li><a href="chapter_{i:03d}.xhtml">{htmlmod.escape(rendered.toc[i][1] if i < len(rendered.toc) else str(i+1))}</a></li>' for i in range(len(rendered.chapter_chunks)))
            z.writestr('OEBPS/nav.xhtml', f'<?xml version="1.0" encoding="UTF-8"?><html xmlns="http://www.w3.org/1999/xhtml"><head><title>{htmlmod.escape(title)}</title></head><body><nav epub:type="toc" id="toc"><ol>{navlis}</ol></nav></body></html>')
    return mem.getvalue(), warnings, None


def render_html_dir(book: Book, outdir: Path) -> Tuple[List[ConfigError], Optional[str]]:
    rendered = render_book_model(book)
    if rendered.error:
        return rendered.warnings, rendered.error
    try:
        outdir.mkdir(parents=False, exist_ok=True)
        (outdir / 'stylesheet.css').write_text(html_style(), encoding='utf-8')
        (outdir / 'print.css').write_text(TEMPLATES.get('html.css.print', ''), encoding='utf-8')
        title = str(book.opts.get('title', ''))
        toc_items = []
        for idx, (_href, label, _kind) in enumerate(rendered.toc[:len(rendered.chapter_chunks)]):
            toc_items.append(f'<li><a href="chapter_{idx:03d}.html#link-{idx+1}">{htmlmod.escape(label)}</a></li>')
        toc = '\n'.join(toc_items)
        for idx, chunk in enumerate(rendered.chapter_chunks):
            label = rendered.toc[idx][1] if idx < len(rendered.toc) else str(idx+1)
            prev_link = f'<p class = "prev_chapter">\n  <a href = "chapter_{idx-1:03d}.html">Previous</a>\n</p>' if idx > 0 else ''
            next_link = f'<p class = "next_chapter">\n  <a href = "chapter_{idx+1:03d}.html">Next</a>\n</p>' if idx + 1 < len(rendered.chapter_chunks) else ''
            page = f'''<!DOCTYPE html>
<html lang="{htmlmod.escape(str(book.opts.get('lang','en')))}">
  <head>
    <meta charset="utf-8">
    <meta name="generator" content="crowbook">
    <meta name="author" content="{htmlmod.escape(str(book.opts.get('author','')), quote=True)}">
    <meta name="viewport" content="width=device-width">
    <title>{htmlmod.escape(title)} - {htmlmod.escape(label)}</title>
    <link rel = "stylesheet" href = "stylesheet.css" type = "text/css"
          />
    <link rel = "stylesheet" href = "print.css" type = "text/css"
          />
  </head>
  <body>
    <nav><h2><a href = "index.html">{htmlmod.escape(title)}</a></h2><ul>{toc}</ul></nav>
    {prev_link}
    {chunk}
    {next_link}
  </body>
</html>
'''
            (outdir / f'chapter_{idx:03d}.html').write_text(page, encoding='utf-8')
        # The reference version in this environment reports a template error for
        # index.html because `favicon` is missing, but still writes chapters.
        return rendered.warnings, "Error compiling template: render error\n\n  --> <anonymous>:8:7\n   |\n 8 |     {{favicon}}\n   |       ^^^^^^^\n   |\n   = reason: not found in this scope"
    except OSError as e:
        return rendered.warnings, f"could not create HTML directory '{outdir}': {e}"


# ---------------------------------------------------------------------------
# Actions and reporting


def create_book_text(files: List[str]) -> str:
    return CREATE_TEMPLATE_HEAD + ''.join(f'+ {f}\n' for f in files)


def action_create(opts: CliOptions) -> int:
    print_header(opts)
    text = create_book_text(opts.create or [])
    if opts.book:
        p = Path(opts.book)
        if p.exists():
            stderr_write(f"ERROR Could not create file {opts.book}: it already exists!\n")
            return 0
        try:
            p.write_text(text, encoding='utf-8')
        except OSError as e:
            stderr_write(f"ERROR Could not create file {opts.book}: {e}\n")
            return 0
        stdout_write(f"Created {opts.book}, now you'll have to complete it!\n")
    else:
        stdout_write(text)
    return 0


def apply_sets(book: Book, opts: CliOptions) -> Optional[str]:
    vals = opts.set_values
    if not vals:
        return None
    if len(vals) % 2 == 1:
        return "An odd number of arguments was passed to --set, but it takes\na list of key value pairs.\n"
    for i in range(0, len(vals), 2):
        key, val = vals[i], vals[i+1]
        before = len(book.errors)
        set_book_option(book, key, val, 2, book.source)
        if len(book.errors) > before:
            err = book.errors.pop().msg
            return f"Error in setting key {key}: {err}"
    return None


def print_aggregated(opts: CliOptions, messages: List[ConfigError]) -> None:
    if not messages:
        return
    if opts.quiet:
        for m in messages:
            if m.level == "ERROR":
                stderr_write(f"[ERROR] {m.msg}\n")
        return
    stderr_write("WARNING Crowbook exited successfully, but the following errors occurred:\n")
    for m in messages:
        stderr_write(f"{m.level} {m.msg}\n")


def path_with_base(book: Book, path: str) -> Path:
    p = Path(path)
    base = str(book.opts.get('output.base_path', '') or '')
    if base and not p.is_absolute():
        p = Path(base) / p
    return p


def write_text_output(path: Path, text: str) -> Optional[str]:
    try:
        path.write_text(text, encoding='utf-8')
        return None
    except OSError as e:
        return f"could not create file '{path}': '{e.strerror or e}' (os error {getattr(e, 'errno', '?')})"


def write_bytes_output(path: Path, data: bytes) -> Optional[str]:
    try:
        path.write_bytes(data)
        return None
    except OSError as e:
        return f"could not create file '{path}': '{e.strerror or e}' (os error {getattr(e, 'errno', '?')})"


def render_one(book: Book, fmt: str, dest: Optional[str], direct: bool) -> Tuple[List[ConfigError], Optional[str]]:
    """Render one format. Returns warnings/errors-list and direct error string."""
    collected: List[ConfigError] = []
    if fmt == 'html':
        text, warns, err = render_html_document(book); collected.extend(warns)
        if err: return collected, err if direct else f"Error rendering html: {err}"
        if dest is None or dest == '-':
            stdout_write(text or '')
        else:
            e = write_text_output(path_with_base(book, dest), text or '')
            if e: return collected, e if direct else f"Error rendering html: {e}"
        return collected, None
    if fmt == 'tex':
        text, warns, err = render_tex_document(book); collected.extend(warns)
        if err: return collected, err if direct else f"Error rendering tex: {err}"
        if dest is None or dest == '-':
            stdout_write(text or '')
        else:
            e = write_text_output(path_with_base(book, dest), text or '')
            if e: return collected, e if direct else f"Error rendering tex: {e}"
        return collected, None
    if fmt == 'epub':
        data, warns, err = render_epub_bytes(book); collected.extend(warns)
        if err: return collected, err if direct else f"Error rendering epub: {err}"
        if dest is None or dest == '-':
            sys.stdout.buffer.write(data or b'')
        else:
            e = write_bytes_output(path_with_base(book, dest), data or b'')
            if e: return collected, e if direct else f"Error rendering epub: {e}"
        return collected, None
    if fmt == 'pdf':
        msg = "Error during temporary files editing: failed to run command 'xelatex'"
        return collected, msg if direct else f"Error rendering pdf: {msg}"
    if fmt == 'html.dir':
        if dest is None or dest == '-':
            msg = "Error during rendering: can only render HTML directory to a path, not to a stream"
            return collected, msg if direct else f"Error rendering html.dir: {msg}"
        warns, err = render_html_dir(book, path_with_base(book, dest)); collected.extend(warns)
        if err: return collected, err if direct else f"Error rendering html.dir: {err.splitlines()[0] if err else err}"
        return collected, None
    if fmt == 'odt':
        return collected, "unknown format odt" if direct else None
    return collected, f"unknown format {fmt}"


def configured_outputs(book: Book) -> List[Tuple[str, str]]:
    outs: List[Tuple[str, str]] = []
    # Explicit paths render in Crowbook's internal order: tex, html, epub, pdf-ish.
    for fmt, key in [('tex','output.tex'), ('html','output.html'), ('epub','output.epub'), ('pdf','output.pdf'), ('html.dir','output.html.dir')]:
        if key in book.opts and book.opts.get(key) not in (None, ''):
            outs.append((fmt, str(book.opts[key])))
    outlist = book.opts.get('output')
    if isinstance(outlist, list):
        stem = book.source.stem
        for fmt in outlist:
            if fmt == 'html' and not any(f == 'html' for f, _ in outs): outs.append(('html', stem + '.html'))
            elif fmt == 'epub' and not any(f == 'epub' for f, _ in outs): outs.append(('epub', stem + '.epub'))
            elif fmt == 'tex' and not any(f == 'tex' for f, _ in outs): outs.append(('tex', stem + '.tex'))
            elif fmt == 'pdf' and not any(f == 'pdf' for f, _ in outs): outs.append(('pdf', stem + '.pdf'))
            elif fmt == 'html.dir' and not any(f == 'html.dir' for f, _ in outs): outs.append(('html.dir', stem))
            # odt is accepted but ignored in this observed build.
    return outs


def action_stats(book: Book, opts: CliOptions) -> int:
    print_header(opts)
    rendered = render_book_model(book)
    if rendered.error:
        stderr_write(f"ERROR {rendered.error}\n")
        return 0
    rows = rendered.stats_rows
    max_name = max((len(r[0]) for r in rows), default=0)
    first_width = max_name + 7
    stdout_write(f"{'Chapter':<{first_width}}{'Chars':>5}{'Words':>11}{'Chars/Word':>12}\n")
    stdout_write("---------\n")
    total_chars = 0; total_words = 0
    for name, chars, words in rows:
        total_chars += chars; total_words += words
        avg = (chars / words) if words else 0.0
        stdout_write(f"{name:<{first_width}}{chars:>5}{words:>11}{avg:>12.2f}\n")
    stdout_write("---------\n")
    avg = (total_chars / total_words) if total_words else 0.0
    stdout_write(f"{'TOTAL:':<{first_width}}{total_chars:>5}{total_words:>11}{avg:>12.2f}\n\n")
    return 0


def load_book_for_action(opts: CliOptions) -> Optional[Book]:
    if not opts.book:
        runtime_error(opts, "You must pass the name of a book configuration file.\nFor more information try --help.\n")
        return None
    path = Path(opts.book)
    if opts.single:
        book = parse_single_markdown(path)
    else:
        book = parse_config_file(path)
    if book.fatal:
        runtime_error(opts, book.fatal)
        return None
    set_err = apply_sets(book, opts)
    if set_err:
        runtime_error(opts, set_err)
        return None
    if opts.autograph:
        stdout_write("Enter autograph:\n")
        try:
            val = sys.stdin.readline().rstrip('\n')
        except Exception:
            val = ''
        if val:
            book.opts['autograph'] = val
    return book


def action_render(book: Book, opts: CliOptions) -> int:
    print_header(opts)
    messages: List[ConfigError] = list(book.errors)
    if opts.to:
        dest = opts.output
        if dest is None:
            key = 'output.' + opts.to
            if opts.to == 'html.dir': key = 'output.html.dir'
            if key in book.opts and book.opts.get(key):
                dest = str(book.opts[key])
        warns, err = render_one(book, opts.to, dest, direct=True)
        messages.extend(warns)
        if err:
            stderr_write(f"ERROR {err}\n")
        else:
            # Direct EPUB still reports fallback warning, normal direct modes do not aggregate errors.
            if not opts.quiet:
                for m in messages:
                    if m.level == 'WARNING':
                        # Reference uses aggregate wording for EPUB fallback even in direct mode.
                        stderr_write("WARNING Crowbook exited successfully, but the following errors occurred:\n")
                        for mm in messages:
                            stderr_write(f"{mm.level} {mm.msg}\n")
                        break
            elif any(m.level == 'ERROR' for m in messages):
                for m in messages:
                    if m.level == 'ERROR': stderr_write(f"[ERROR] {m.msg}\n")
        return 0

    outs = configured_outputs(book)
    for fmt, dest in outs:
        warns, err = render_one(book, fmt, dest, direct=False)
        messages.extend(warns)
        if err:
            messages.append(ConfigError("ERROR", err))
    print_aggregated(opts, messages)
    return 0


def main(argv: List[str]) -> int:
    opts, code = parse_cli(argv)
    if code is not None:
        return code
    assert opts is not None

    if opts.list_options:
        print_header(opts)
        stdout_write(LIST_OPTIONS)
        return 0
    if opts.print_template is not None:
        print_header(opts)
        if opts.print_template in TEMPLATES:
            stdout_write(TEMPLATES[opts.print_template])
        else:
            stderr_write(f"ERROR {opts.print_template} is not a valid template name\n")
        return 0
    if opts.create is not None:
        return action_create(opts)

    book = load_book_for_action(opts)
    if book is None:
        return 0
    if opts.stats:
        return action_stats(book, opts)
    return action_render(book, opts)


if __name__ == '__main__':
    try:
        sys.exit(main(sys.argv[1:]))
    except BrokenPipeError:
        try:
            sys.stderr.close()
        finally:
            sys.exit(0)
