CREATE_TEMPLATE_HEAD = """\"author: Your name\"
\"title: Your title\"
\"lang: en\"

\"## Output formats\"

\"# Uncomment and fill to generate files\"
\"# output.html: some_file.html\"
\"# output.epub: some_file.epub\"
\"# output.pdf: some_file.pdf\"

\"# Or uncomment the following to generate PDF, HTML and EPUB files based on this file's name\"
\"# output: [pdf, epub, html]\"

\"# Uncomment and fill to set cover image (for EPUB)\"
\"# cover: some_cover.png\"

## List of chapters
"""

TO_CHOICES = {"epub", "pdf", "html", "tex", "odt", "html.dir"}

# Known configuration keys.  Unknown keys are reported like the reference, but
# most known keys can be safely stored as strings because only a subset affects
# this compact renderer.
META_KEYS = {
    "author", "title", "lang", "subject", "description", "cover",
    "subtitle", "license", "version", "date", "autograph",
}
PATH_KEYS = {
    "output.epub", "output.html", "output.html.dir", "output.tex",
    "output.pdf", "output.base_path", "output.odt", "import", "html.icon",
    "html.css", "html.css.colors", "html.js", "html.css.print",
    "html.highlight.js", "html.highlight.css", "html.standalone.template",
    "html.standalone.js", "html.dir.template", "epub.css",
    "epub.chapter.xhtml", "epub.titlepage.xhtml", "tex.template",
    "resources.out_path", "resources.base_path", "resources.base_path.links",
    "resources.base_path.images", "resources.base_path.files",
    "resources.base_path.templates", "crowbook.temp_dir",
}
STRING_KEYS = {
    "rendering.highlight", "rendering.highlight.theme", "rendering.chapter",
    "rendering.part", "rendering.inline_toc.name", "rendering.chapter.template",
    "rendering.part.template", "html.highlight.theme", "html.header",
    "html.footer", "html.css.add", "epub.highlight.theme", "epub.css.add",
    "tex.highlight.theme", "tex.pageref_template", "tex.command",
    "tex.template.add", "tex.class", "tex.paper.size", "tex.margin.left",
    "tex.margin.right", "tex.margin.top", "tex.margin.bottom",
    "resources.files", "crowbook.zip.command",
}
BOOL_KEYS = {
    "rendering.initials", "rendering.inline_toc", "rendering.chapter.roman_numerals",
    "rendering.part.roman_numerals", "rendering.part.reset_counter",
    "html.side_notes", "html.escape_nb_spaces", "html.standalone.one_chapter",
    "epub.toc.extras", "epub.escape_nb_spaces", "tex.cover",
    "tex.links_as_footnotes", "tex.escape_nb_spaces", "tex.title",
    "tex.hyperref", "tex.stdpage", "input.clean", "input.clean.smart_quotes",
    "input.clean.ligature.dashes", "input.clean.ligature.guillemets",
    "input.yaml_blocks", "crowbook.html_as_text", "crowbook.files_mean_chapters",
    "crowbook.markdown.superscript",
}
INT_KEYS = {"rendering.num_depth", "epub.version", "tex.font.size"}
LIST_KEYS = {"output"}
KNOWN_KEYS = META_KEYS | PATH_KEYS | STRING_KEYS | BOOL_KEYS | INT_KEYS | LIST_KEYS


def stderr_write(s: str) -> None:
    sys.stderr.write(s)


def stdout_write(s: str) -> None:
    sys.stdout.write(s)


def print_header(opts: "CliOptions") -> None:
    if not opts.quiet:
        stderr_write(HEADER)


def runtime_error(opts: "CliOptions", msg: str) -> None:
    print_header(opts)
    stderr_write(f"ERROR {msg}\n")


def clap_error(msg: str, usage: Optional[str] = None, possible: bool = False) -> int:
    stderr_write(msg)
    if usage:
        stderr_write(f"\nUsage: {usage}\n")
    stderr_write("\nFor more information, try '--help'.\n")
    return 2


def unexpected_arg(arg: str) -> int:
    tip = ""
    if arg.startswith("-"):
        tip = f"\n  tip: to pass '{arg}' as a value, use '-- {arg}'\n"
    return clap_error(f"error: unexpected argument '{arg}' found\n{tip}", "executable [OPTIONS] [BOOK]")


def invalid_to(value: str) -> int:
    stderr_write(f"error: invalid value '{value}' for '--to <to>'\n")
    stderr_write("  [possible values: epub, pdf, html, tex, odt, html.dir]\n")
    stderr_write("\nFor more information, try '--help'.\n")
    return 2


def missing_value(opt: str, value_name: str, possible_to: bool = False) -> int:
    stderr_write(f"error: a value is required for '{opt} <{value_name}>' but none was supplied\n")
    if possible_to:
        stderr_write("  [possible values: epub, pdf, html, tex, odt, html.dir]\n")
    stderr_write("\nFor more information, try '--help'.\n")
    return 2


def required_to(output_present: bool, book_present: bool) -> int:
    stderr_write("error: the following required arguments were not provided:\n  --to <to>\n\n")
    book = "<BOOK>" if book_present else "[BOOK]"
    stderr_write(f"Usage: executable --to <to> --output <output> {book}\n")
    stderr_write("\nFor more information, try '--help'.\n")
    return 2


@dataclass
class CliOptions:
    force_emoji: bool = False
    single: bool = False
    no_fancy: bool = False
    verbose: bool = False
    autograph: bool = False
    quiet: bool = False
    create: Optional[List[str]] = None
    output: Optional[str] = None
    to: Optional[str] = None
    set_values: List[str] = field(default_factory=list)
    list_options: bool = False
    runtime_lang: Optional[str] = None
    print_template: Optional[str] = None
    stats: bool = False
    book: Optional[str] = None


def parse_cli(argv: List[str]) -> Tuple[Optional[CliOptions], Optional[int]]:
    opts = CliOptions()
    i = 0
    stop_options = False

    def need_next(opt: str, value_name: str, possible_to: bool = False) -> Optional[str]:
        nonlocal i
        if i + 1 >= len(argv) or (argv[i + 1].startswith('-') and argv[i + 1] != '-'):
            code = missing_value(opt, value_name, possible_to)
            raise SystemExit(code)
        i += 1
        return argv[i]

    while i < len(argv):
        arg = argv[i]
        if stop_options:
            if opts.book is None:
                opts.book = arg
            else:
                return None, unexpected_arg(arg)
            i += 1
            continue
        if arg == "--":
            stop_options = True
            i += 1
            continue
        if arg in ("--help", "-h"):
            stdout_write(HELP_TEXT)
            return None, 0
        if arg in ("--version", "-V"):
            stdout_write(f"crowbook {VERSION}\n")
            return None, 0
        if arg.startswith("--"):
            name, eq, val = arg.partition('=')
            if name == "--force-emoji":
                opts.force_emoji = True
            elif name == "--single":
                opts.single = True
            elif name == "--no-fancy":
                opts.no_fancy = True
            elif name == "--verbose":
                opts.verbose = True
            elif name == "--autograph":
                opts.autograph = True
            elif name == "--quiet":
                opts.quiet = True
            elif name == "--list-options":
                opts.list_options = True
            elif name == "--stats":
                opts.stats = True
            elif name == "--lang":
                if eq:
                    opts.runtime_lang = val
                else:
                    try:
                        opts.runtime_lang = need_next("--lang", "lang")
                    except SystemExit as e:
                        return None, int(e.code)
            elif name == "--output":
                if eq:
                    opts.output = val
                else:
                    try:
                        opts.output = need_next("--output", "output")
                    except SystemExit as e:
                        return None, int(e.code)
            elif name == "--to":
                if eq:
                    opts.to = val
                else:
                    try:
                        opts.to = need_next("--to", "to", True)
                    except SystemExit as e:
                        return None, int(e.code)
                if opts.to not in TO_CHOICES:
                    return None, invalid_to(opts.to)
            elif name == "--print-template":
                if eq:
                    opts.print_template = val
                else:
                    try:
                        opts.print_template = need_next("--print-template", "print-template")
                    except SystemExit as e:
                        return None, int(e.code)
            elif name == "--create":
                vals: List[str] = []
                if eq and val:
                    vals.append(val)
                j = i + 1
                while j < len(argv) and not argv[j].startswith('-'):
                    vals.append(argv[j]); j += 1
                if not vals:
                    stderr_write("error: a value is required for '--create <files>...' but none was supplied\n")
                    stderr_write("\nFor more information, try '--help'.\n")
                    return None, 2
                opts.create = vals
                i = j - 1
            elif name == "--set":
                vals: List[str] = []
                if eq and val:
                    vals.append(val)
                j = i + 1
                while j < len(argv) and not argv[j].startswith('-'):
                    vals.append(argv[j]); j += 1
                if len(vals) == 0:
                    stderr_write("error: a value is required for '--set <set> <set>...' but none was supplied\n")
                    stderr_write("\nFor more information, try '--help'.\n")
                    return None, 2
                if len(vals) == 1:
                    stderr_write("error: 2 values required by '--set <set> <set>...'; only 1 was provided\n\n")
                    stderr_write("Usage: executable [OPTIONS] [BOOK]\n")
                    stderr_write("\nFor more information, try '--help'.\n")
                    return None, 2
                opts.set_values.extend(vals)
                i = j - 1
            else:
                return None, unexpected_arg(arg)
            i += 1
            continue
        if arg.startswith('-') and arg != '-':
            # Short option cluster, supporting attached values for -t/-o/-L/-c.
            cluster = arg[1:]
            k = 0
            while k < len(cluster):
                ch = cluster[k]
                rest = cluster[k + 1:]
                if ch == 'h':
                    stdout_write(HELP_TEXT); return None, 0
                if ch == 'V':
                    stdout_write(f"crowbook {VERSION}\n"); return None, 0
                if ch == 'f': opts.force_emoji = True; k += 1; continue
                if ch == 's': opts.single = True; k += 1; continue
                if ch == 'n': opts.no_fancy = True; k += 1; continue
                if ch == 'v': opts.verbose = True; k += 1; continue
                if ch == 'a': opts.autograph = True; k += 1; continue
                if ch == 'q': opts.quiet = True; k += 1; continue
                if ch == 'l': opts.list_options = True; k += 1; continue
                if ch == 'S': opts.stats = True; k += 1; continue
                if ch in ('t', 'o', 'L', 'c'):
                    val = rest
                    if val.startswith('='):
                        val = val[1:]
                    if not val:
                        if i + 1 >= len(argv) or (argv[i + 1].startswith('-') and argv[i + 1] != '-'):
                            if ch == 't': return None, missing_value("--to", "to", True)
                            if ch == 'o': return None, missing_value("--output", "output")
                            if ch == 'L': return None, missing_value("--lang", "lang")
                            stderr_write("error: a value is required for '--create <files>...' but none was supplied\n")
                            stderr_write("\nFor more information, try '--help'.\n")
                            return None, 2
                        i += 1; val = argv[i]
                    if ch == 't':
                        opts.to = val
                        if opts.to not in TO_CHOICES: return None, invalid_to(opts.to)
                    elif ch == 'o':
                        opts.output = val
                    elif ch == 'L':
                        opts.runtime_lang = val
                    elif ch == 'c':
                        vals = [val]
                        j = i + 1
                        while j < len(argv) and not argv[j].startswith('-'):
                            vals.append(argv[j]); j += 1
                        opts.create = vals
                        i = j - 1
                    k = len(cluster)
                    continue
                return None, unexpected_arg('-' + ch)
            i += 1
            continue
        # Positional BOOK.
        if opts.book is None:
            opts.book = arg
        else:
            return None, unexpected_arg(arg)
        i += 1

    if opts.output is not None and opts.to is None:
        return None, required_to(True, opts.book is not None)
    return opts, None


