@dataclass
class ConfigError:
    level: str  # ERROR or WARNING
    msg: str


@dataclass
class ChapterSpec:
    marker: str
    target: str
    line: int


@dataclass
class Book:
    source: Path
    base_dir: Path
    opts: Dict[str, object] = field(default_factory=dict)
    chapters: List[ChapterSpec] = field(default_factory=list)
    errors: List[ConfigError] = field(default_factory=list)
    fatal: Optional[str] = None
    single_body: Optional[str] = None

    def __post_init__(self) -> None:
        defaults = {
            "author": "", "title": "", "lang": "en",
            "output.base_path": "", "rendering.highlight": "syntect",
            "rendering.highlight.theme": "InspiredGitHub",
            "rendering.initials": False, "rendering.inline_toc": False,
            "rendering.inline_toc.name": "{{loc_toc}}",
            "rendering.num_depth": 1,
            "rendering.chapter.roman_numerals": False,
            "rendering.part.roman_numerals": True,
            "rendering.part.reset_counter": True,
            "rendering.chapter.template": "{{number}}. {{chapter_title}}",
            "rendering.part.template": "{{number}}. {{part_title}}",
            "html.escape_nb_spaces": True, "epub.version": 2,
            "epub.toc.extras": True, "epub.escape_nb_spaces": True,
            "tex.command": "xelatex", "tex.escape_nb_spaces": True,
            "tex.class": "book", "tex.paper.size": "a5paper",
            "tex.margin.top": "2cm", "tex.margin.bottom": "1.5cm",
            "tex.title": True, "tex.hyperref": True, "tex.stdpage": False,
            "resources.out_path": "data", "resources.base_path.images": ".",
