@dataclass
class RenderState:
    book: Book
    html: bool = True
    link_counter: int = 1
    para_counter: int = 1
    chapter_counter: int = 0
    part_counter: int = 0
    section_stack: List[int] = field(default_factory=lambda: [0, 0, 0, 0, 0, 0])
