    warnings: List[ConfigError] = field(default_factory=list)
    image_error: Optional[str] = None


def roman(n: int) -> str:
    vals = [(1000,'M'),(900,'CM'),(500,'D'),(400,'CD'),(100,'C'),(90,'XC'),(50,'L'),(40,'XL'),(10,'X'),(9,'IX'),(5,'V'),(4,'IV'),(1,'I')]
    out = []
    for v, s in vals:
        while n >= v:
            out.append(s); n -= v
    return ''.join(out) or '0'


def lang_chapter(book: Book) -> str:
    custom = book.opts.get("rendering.chapter")
    if custom:
        return str(custom)
    return "Chapitre" if str(book.opts.get("lang", "en")).startswith('fr') else "Chapter"


def lang_part(book: Book) -> str:
    custom = book.opts.get("rendering.part")
    if custom:
        return str(custom)
    return "Partie" if str(book.opts.get("lang", "en")).startswith('fr') else "Part"


def clean_text(text: str, book: Book) -> str:
    if not bool(book.opts.get("input.clean", True)):
        return text
    if bool(book.opts.get("input.clean.smart_quotes", True)):
        # A deterministic, lightweight smart quote pass.
        res = []
        open_d = True
        for ch in text:
            if ch == '"':
                res.append('“' if open_d else '”'); open_d = not open_d
            else:
                res.append(ch)
        text = ''.join(res)
        # Apostrophes between letters are closing apostrophes; remaining pairs alternate.
        text = re.sub(r"(?<=\w)'(?=\w)", "’", text)
        res = []
        open_s = True
        for ch in text:
            if ch == "'":
                res.append('‘' if open_s else '’'); open_s = not open_s
            else:
                res.append(ch)
        text = ''.join(res)
    if bool(book.opts.get("input.clean.ligature.dashes", False)):
        text = text.replace('---', '—').replace('--', '–')
    if str(book.opts.get("lang", "en")).startswith('fr'):
        text = text.replace('...', '…')
        if bool(book.opts.get("input.clean.ligature.guillemets", False)):
            text = text.replace('<<', '«').replace('>>', '»')
    return text


def apply_french_nbsp_escaped(escaped: str, book: Book, epub: bool = False) -> str:
    if not str(book.opts.get("lang", "en")).startswith('fr'):
        return escaped
    if not bool(book.opts.get("html.escape_nb_spaces", True)):
        return escaped
    # Approximation of Crowbook's non-breaking-space cleaning before high
    # punctuation. Keep it as an entity after escaping.
    escaped = re.sub(r"\s+([!?:;])", r"&#160;\1", escaped)
    return escaped


def escape_html_text(text: str, book: Book) -> str:
    text = clean_text(text, book)
    esc = htmlmod.escape(text, quote=False)
    esc = apply_french_nbsp_escaped(esc, book)
    return esc


def inline_stats_text(src: str, book: Book) -> str:
    s = re.sub(r"!\[[^\]]*\]\([^)]*\)", "", src)
    s = re.sub(r"\[([^\]]+)\]\([^)]*\)", r"\1", s)
    s = re.sub(r"`([^`]*)`", r"\1", s)
    s = re.sub(r"\*\*([^*]+)\*\*", r"\1", s)
    s = re.sub(r"\*([^*]+)\*", r"\1", s)
    s = re.sub(r"__([^_]+)__", r"\1", s)
    s = re.sub(r"_([^_]+)_", r"\1", s)
    s = re.sub(r"<[^>]+>", lambda m: m.group(0), s)  # tags count as text if present before escaping
    return clean_text(s, book)


def local_path_for(md_path: Path, target: str) -> Path:
    p = Path(target)
    if p.is_absolute():
        return p
    return (md_path.parent if md_path.parent != Path('') else Path('.')) / p


def render_inline(src: str, book: Book, md_path: Path, state: RenderState) -> str:
    # Tokenize image/link/code/emphasis enough for common Markdown.
    placeholders: List[str] = []

    def put(x: str) -> str:
        placeholders.append(x)
        return f"\u0000{len(placeholders)-1}\u0000"

    def image_repl(m: re.Match) -> str:
        alt, url = m.group(1), m.group(2).strip()
        if not re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*:", url):
            p = local_path_for(md_path, url)
            if not p.exists():
                disp = url if url.startswith('.') else './' + url
                state.image_error = f"{md_path.name}: Could not find file '{disp}' for image"
                return ""
            data = p.read_bytes()
            mime = mimetypes.guess_type(str(p))[0] or "application/octet-stream"
            b64 = base64.b64encode(data).decode('ascii').rstrip('=')
            return put(f'<img src = "data:{mime};base64,{b64}" title = "" alt = "{htmlmod.escape(clean_text(alt, book), quote=True)}" />')
        return put(f'<img src = "{htmlmod.escape(url, quote=True)}" title = "" alt = "{htmlmod.escape(clean_text(alt, book), quote=True)}" />')

    src = re.sub(r"!\[([^\]]*)\]\(([^)]*)\)", image_repl, src)

    def code_repl(m: re.Match) -> str:
        return put(f"<code>{escape_html_text(m.group(1), book)}</code>")
    src = re.sub(r"`([^`]*)`", code_repl, src)

    def link_repl(m: re.Match) -> str:
        text, url = m.group(1), m.group(2).strip()
        inner = render_inline(text, book, md_path, state)
        if not re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*:", url) and not url.startswith('#'):
            # The reference warns for local links that do not point to a known chapter.
            # Keep warning wording for obvious standalone local files.
            pass
        return put(f'<a href = "{htmlmod.escape(url, quote=True)}">{inner}</a>')
    src = re.sub(r"\[([^\]]+)\]\(([^)]*)\)", link_repl, src)

    # Escape remaining text, then restore placeholders.
    s = escape_html_text(src, book)

    def strong(m: re.Match) -> str:
        return f"<b>{m.group(1)}</b>"
    def emph(m: re.Match) -> str:
        return f"<em>{m.group(1)}</em>"
    s = re.sub(r"\*\*([^*]+)\*\*", strong, s)
    s = re.sub(r"__([^_]+)__", strong, s)
    s = re.sub(r"\*([^*]+)\*", emph, s)
    s = re.sub(r"_([^_]+)_", emph, s)

    def restore(m: re.Match) -> str:
        return placeholders[int(m.group(1))]
    s = re.sub("\u0000(\d+)\u0000", restore, s)
    return s


def render_paragraph(lines: List[str], book: Book, md_path: Path, state: RenderState) -> Tuple[str, str]:
    # Markdown hard break: two trailing spaces before a line break.
    pieces = []
    stat = []
    for idx, line in enumerate(lines):
        hard = line.endswith('  ')
        content = line[:-2] if hard else line
        pieces.append(render_inline(content, book, md_path, state))
        stat.append(inline_stats_text(content, book))
        if hard:
            pieces.append('<br />\n')
        elif idx != len(lines) - 1:
            pieces.append('\n')
    pid = state.para_counter; state.para_counter += 1
    return f'<p id = "para-{pid}">' + ''.join(pieces) + '</p>', ''.join(stat)


def heading_number_prefix(level: int, state: RenderState, book: Book) -> str:
    depth = int(book.opts.get("rendering.num_depth", 1) or 0)
    if depth < level or level <= 1:
        return ""
    # Increment this level and reset deeper counters. H1 counter is chapter_counter.
    state.section_stack[level-1] += 1
    for i in range(level, len(state.section_stack)):
        state.section_stack[i] = 0
    nums = [state.chapter_counter] + state.section_stack[1:level]
    return '.'.join(str(n) for n in nums if n) + '. '


def make_toc_label(number: str, title: str, marker: str, book: Book, part: bool = False) -> str:
    if part:
        tmpl = str(book.opts.get("rendering.part.template", "{{number}}. {{part_title}}"))
        return tmpl.replace("{{number}}", number).replace("{{part_title}}", title)
    if marker == '+':
        tmpl = str(book.opts.get("rendering.chapter.template", "{{number}}. {{chapter_title}}"))
        return tmpl.replace("{{number}}", number).replace("{{chapter_title}}", title)
    return title


def render_h1(title_src: str, marker: str, book: Book, state: RenderState, md_path: Path) -> str:
    title_text = inline_stats_text(title_src, book)
    link = state.link_counter; state.link_counter += 1
    depth = int(book.opts.get("rendering.num_depth", 1) or 0)
    if marker == '+' and depth > 0:
        state.chapter_counter += 1
        state.section_stack = [0, 0, 0, 0, 0, 0]
        num = roman(state.chapter_counter) if bool(book.opts.get("rendering.chapter.roman_numerals", False)) else str(state.chapter_counter)
        state.toc.append((f"#link-{link}", make_toc_label(num, title_text, marker, book), "chapter"))
        header = f"{lang_chapter(book)} {num}"
        title_html = render_inline(title_src, book, md_path, state)
        if title_text:
            return f"<h1 id = 'link-{link}'><span class = 'chapter-header'>{htmlmod.escape(header)}</span><br />{title_html}</h1>"
        return f"<h1 id = 'link-{link}'><span class = 'chapter-header'>{htmlmod.escape(header)}</span></h1>"
    if marker == '!' and depth > 0:
        state.toc.append((f"#link-{link}", title_text, "chapter"))
        return f'<h1 id = "link-{link}"></h1>'
    # Unnumbered or no-number-depth.
    if depth > 0 and title_text:
        state.toc.append((f"#link-{link}", title_text, "chapter"))
    title_html = render_inline(title_src, book, md_path, state)
    return f'<h1 id = "link-{link}">{title_html}</h1>'


def render_markdown_body(text: str, book: Book, md_path: Path, marker: str, state: RenderState) -> Tuple[str, str, bool]:
    lines = text.splitlines()
    out: List[str] = []
    stats_parts: List[str] = []
    saw_h1 = False
    i = 0

    def ensure_initial_chapter() -> None:
        nonlocal saw_h1
        if saw_h1:
            return
        if marker == '+' and int(book.opts.get("rendering.num_depth", 1) or 0) > 0:
            # A numbered file without an H1 still gets a chapter heading and TOC item.
            saw_h1 = True
            link = state.link_counter; state.link_counter += 1
            state.chapter_counter += 1
            state.section_stack = [0, 0, 0, 0, 0, 0]
            num = roman(state.chapter_counter) if bool(book.opts.get("rendering.chapter.roman_numerals", False)) else str(state.chapter_counter)
            state.toc.append((f"#link-{link}", make_toc_label(num, "", marker, book), "chapter"))
            out.append(f"<h1 id = 'link-{link}'><span class = 'chapter-header'>{htmlmod.escape(lang_chapter(book))} {num}</span></h1>")

    while i < len(lines):
        line = lines[i]
        stripped = line.strip()
        if stripped == '':
            i += 1; continue
        # Fenced code block
        m = re.match(r"^```\s*([^`]*)$", line)
        if m:
            ensure_initial_chapter()
            lang = m.group(1).strip()
            i += 1; code_lines = []
            while i < len(lines) and not lines[i].startswith('```'):
                code_lines.append(lines[i]); i += 1
            if i < len(lines): i += 1
            code = '\n'.join(code_lines) + '\n'
            stats_parts.append(code)
            esc = htmlmod.escape(code, quote=False)
            if lang:
                out.append(f'<pre><code class = "language-{htmlmod.escape(lang, quote=True)}">{esc}</code></pre>')
            else:
                out.append(f'<pre><code>{esc}</code></pre>')
            continue
        # Heading
        hm = re.match(r"^(#{1,6})\s+(.*?)\s*#*\s*$", line)
        if hm:
            level = len(hm.group(1)); title_src = hm.group(2)
            if level == 1:
                saw_h1 = True
                stats_parts.append(inline_stats_text(title_src, book))
                out.append(render_h1(title_src, marker, book, state, md_path))
            else:
                ensure_initial_chapter()
                stats_parts.append(inline_stats_text(title_src, book))
                link = state.link_counter; state.link_counter += 1
                prefix = heading_number_prefix(level, state, book)
                out.append(f'<h{level} id = "link-{link}">{htmlmod.escape(prefix)}{render_inline(title_src, book, md_path, state)}</h{level}>')
            i += 1; continue
        # Rule
        if stripped in ('---', '***', '* * *'):
            ensure_initial_chapter()
            out.append('<p class = "rule">***</p>')
            i += 1; continue
        # Block quote (simple)
        if line.lstrip().startswith('>'):
            ensure_initial_chapter()
            qlines = []
            while i < len(lines) and lines[i].lstrip().startswith('>'):
                qlines.append(lines[i].lstrip()[1:].lstrip())
                i += 1
            p, st = render_paragraph(qlines, book, md_path, state)
            stats_parts.append(st)
            out.append('<blockquote>' + p + '\n</blockquote>')
            continue
        # Lists
        if re.match(r"^\s*([-*])\s+\S", line) or re.match(r"^\s*\d+\.\s+\S", line):
            ensure_initial_chapter()
            ordered = bool(re.match(r"^\s*\d+\.\s+", line))
            tag = 'ol' if ordered else 'ul'
            out.append(f'<{tag}>')
            while i < len(lines):
                lm = re.match(r"^\s*(?:[-*]|\d+\.)\s+(.*)$", lines[i])
                if not lm:
                    break
                item = lm.group(1)
                p, st = render_paragraph([item], book, md_path, state)
                stats_parts.append(st)
                out.append('<li>' + p + '\n</li>')
                i += 1
            out.append(f'</{tag}>')
            continue
        # Paragraph
        ensure_initial_chapter()
        plines = []
        while i < len(lines):
            l = lines[i]
            if not l.strip():
                break
            if re.match(r"^```", l) or re.match(r"^(#{1,6})\s+", l) or l.strip() in ('---','***','* * *') or l.lstrip().startswith('>') or re.match(r"^\s*(?:[-*]|\d+\.)\s+\S", l):
                break
            plines.append(l); i += 1
        if plines:
            p, st = render_paragraph(plines, book, md_path, state)
            stats_parts.append(st)
            out.append(p)
        else:
            i += 1
    if not saw_h1 and marker == '+' and not out:
        ensure_initial_chapter()
    return '\n'.join(out), ''.join(stats_parts), saw_h1


@dataclass
class Rendered:
    chapter_divs: List[str]
    chapter_chunks: List[str]
    stats_rows: List[Tuple[str, int, int]]
    toc: List[Tuple[str, str, str]]
    warnings: List[ConfigError]
    error: Optional[str] = None


def render_book_model(book: Book) -> Rendered:
    state = RenderState(book=book)
    chapter_divs: List[str] = []
    chapter_chunks: List[str] = []
    stats_rows: List[Tuple[str, int, int]] = []
    if book.single_body is not None:
        md_path = book.source
        body, stat_text, _ = render_markdown_body(book.single_body, book, md_path, '+', state)
        if state.image_error:
            return Rendered([], [], [], [], state.warnings, state.image_error)
        chapter_divs.append(f'<div id = "chapter-0" class = "chapter">\n  {body}\n</div>')
        chapter_chunks.append(body)
        stats_rows.append((book.source.name, len(stat_text), len(stat_text.split())))
    else:
        file_index = 0
        for spec in book.chapters:
            if spec.marker == '@':
                state.part_counter += 1
                num = roman(state.part_counter) if bool(book.opts.get("rendering.part.roman_numerals", True)) else str(state.part_counter)
                title = spec.target
                link = state.link_counter; state.link_counter += 1
                state.toc.append((f"#link-{link}", make_toc_label(num, title, '@', book, part=True), "part"))
                html = f"<h2 class = 'part'>{htmlmod.escape(lang_part(book))} {num}</h2> <h1 id = 'link-{link}' class = 'part'>{htmlmod.escape(title)}</h1>"
                chapter_divs.append(f'<div id = "chapter-{file_index}" class = "chapter">\n  {html}\n</div>')
                chapter_chunks.append(html)
                stats_rows.append(("", len(title), len(title.split())))
                file_index += 1
                if bool(book.opts.get("rendering.part.reset_counter", True)):
                    state.chapter_counter = 0
                continue
            md_path = Path(spec.target)
            if not md_path.is_absolute():
                md_path = book.base_dir / md_path
            if not md_path.exists():
                return Rendered([], [], [], [], state.warnings, f"{book.source}:{spec.line}: Could not find file '{md_path}' for book chapter")
            try:
                text = md_path.read_text(encoding='utf-8')
            except OSError:
                return Rendered([], [], [], [], state.warnings, f"{book.source}:{spec.line}: Could not find file '{md_path}' for book chapter")
            body, stat_text, _ = render_markdown_body(text, book, md_path, spec.marker, state)
            if state.image_error:
                return Rendered([], [], [], [], state.warnings, state.image_error)
            chapter_divs.append(f'<div id = "chapter-{file_index}" class = "chapter">\n  {body}\n</div>')
            chapter_chunks.append(body)
            stats_rows.append((spec.target, len(stat_text), len(stat_text.split())))
            file_index += 1
    return Rendered(chapter_divs, chapter_chunks, stats_rows, state.toc, state.warnings)


